Lemma ph_sub : forall x y N, 0 <= x < 2 ^ 62 -> 0 <= y <= N -> N < 2 ^ 62 -> 0 <= (x - y) mod 2 ^ 64 <= N -> y <= x.
Proof. intros x y N Hx Hy HN Hm. pose proof (PSB.mod_pos (x - y) 0 N ltac:(lia) ltac:(lia) ltac:(lia) Hm). lia. Qed.
Lemma ph_ec0 : forall i E1 E' (M' : mem) model1 cells, HAMB i E1 M' model1 -> know_ok RSEGS E' M' cells -> env_agree GT.NF E0 E' ->
  PB.has cells (KWord (SA Eb 0) 4 (ELit 0)) = true -> PML.u32 M' E 0.
Proof.
  intros i E1 E' M' model1 cells HA' HK Hag Y.
  pose proof (PSI.OBJR I) as (O1 & O2 & O3 & O4 & O5 & O6 & O7).
  assert (HdE' : L5.defined M' E 16) by (apply (PSB.amb_def I i E1 M' model1 E 16 HA'); [destruct (PSI.iHEC I) as (_ & Q & _); exact Q | lia]).
  exact (proj1 (PSX.ecell0 I E' M' cells HK Hag Y HdE')).
Qed.
Lemma leaf_reH : forall i c k ps1, is_leaf i c k ps1 (CC.TOther HPC) -> CC.leaf_ok (hl_segs L) G.CPS AMB3 K PML.fp_ok i c ps1.
Proof.
  intros i c k ps1 IL.
  pose proof (CH2.leaves_all_sound _ _ _ reH_ok _ _ _ _ _ IL) as X.
  unfold PSM4.reH_chk in X. rewrite Z.eqb_refl in X. cbv beta iota zeta in X.
  destruct (kind_of i) eqn:K1; try discriminate X.
  destruct (PSM2.ldelta i c ps1) as [[[[[pv lv] pe] ce] d]|] eqn:HLD; [|discriminate X].
  destruct (PSM4.meas_cls c) as [cls|] eqn:Hcls; [|discriminate X].
  cbv beta iota in X.
  apply andb_prop in X as [X A19]. apply andb_prop in X as [X A18]. apply andb_prop in X as [X A17]. apply andb_prop in X as [X A16].
  apply andb_prop in X as [X A15]. apply andb_prop in X as [X A14]. apply andb_prop in X as [X A13]. apply andb_prop in X as [X A12].
  apply andb_prop in X as [X A11]. apply andb_prop in X as [X A10]. apply andb_prop in X as [X A9]. apply andb_prop in X as [X A8].
  apply andb_prop in X as [X A7]. apply andb_prop in X as [X A6]. apply andb_prop in X as [X A5]. apply andb_prop in X as [X A4].
  apply andb_prop in X as [X A3]. apply andb_prop in X as [A1 A2].
  assert (Hi : i = I_L0 \/ i = I_L) by (apply orb_prop in A1 as [Q|Q]; apply Nat.eqb_eq in Q; [left|right]; exact Q).
  assert (Hi0 : i <> 0%nat) by (destruct Hi as [-> | ->]; intros Q; cbv in Q; discriminate Q).
  apply (reent_leaf I i c k ps1 HPC IL (proj1 (Z.eqb_eq _ _) A2) A3).
  intros E1 R1 E' R' M1 M' model1 HAt HA HA' HX Hag HLF HagE' HKc HRL.
  pose proof HA as (_ & _ & HagE & _).
  unfold PSI.XI in HX. destruct HX as (X1 & X2 & X3 & HX). rewrite K1 in HX.
  rewrite (PSB.lview_vw _ _ _ _ _ _ _ (ldelta_lview _ _ _ _ _ _ _ _ HLD)) in HX.
  destruct HX as (bm & bd & stack & buf & HC & HS & HW & HB & HWS & HR & HE).
  destruct (PSB.leaf_state I i c k ps1 _ pv lv pe ce d E1 R1 E' R' M1 M' model1 bm bd stack buf IL HLD HAt HA Hag HLF HC)
    as (_ & _ & _ & L1 & L2 & L3 & L4 & L5 & L6 & L7 & (AG1 & AG2 & AG3) & L8 & L9 & L10 & L11 & L12 & L13 & L14 & L15 & L16 & HSB & FR2 & FRI & HPAX & Hden & HEQ).
  pose proof HC as (HC1 & HC2 & HC3 & HC4 & HC5 & HC6 & HC6b & HC7 & HC8 & HC9).
  destruct (PSM2.d_st d) eqn:Dst; [discriminate A5|].
  destruct (PSM2.d_sst d) eqn:Dsst; [discriminate A6|].
  destruct (PSM2.d_nst d) eqn:Dnst; [discriminate A7|].
  destruct (PSM2.d_more d) eqn:Dmore; [discriminate A8|].
  destruct (PSM2.d_done d) eqn:Ddone; [discriminate A9|].
  destruct (PSM2.d_clr d) eqn:Dclr; [discriminate A10|].
  cbn [PSB.newv] in L8, L9, L10, L11, L12, L13.
  apply Z.eqb_eq in A11. rewrite A11, Z.add_0_r in L14.
  set (psc := PSI.ps_of pv pe ce E1 bm bd stack buf) in *.
  destruct (PSB.FRZ I E1 HagE) as (_ & _ & _ & _ & F5 & F6 & _).
  change (uv E1 (EVar 32) = seg) in F5. change (uv E1 (EVar 33) = wlen) in F6.
  pose proof (PSI.WIN I) as (W0 & W1 & W2 & _).
  assert (Hwl : wlen = wend - seg) by reflexivity.
  pose proof HAt as (_ & HKA). rewrite LS in HKA.
  pose proof (PB.has_ok E1 M1 _ _ HKA A18) as F18. cbn [kentry_ok] in F18. fold (uv E1 (EVar 49)) in F18.
  pose proof (PB.has_ok E1 M1 _ _ HKA A17) as F17. cbn [kentry_ok] in F17. fold (uv E1 (APC.esub (EVar 33) (EVar 49))) in F17.
  rewrite PB.uv_esub, F6 in F17.
  pose proof (ph_sub wlen (uv E1 (EVar 49)) _ ltac:(lia) F18 ltac:(lia) F17) as Hjw.
  assert (HCJ : uv E1 PSM4.CURJ = wend - uv E1 (EVar 49)).
  { unfold PSM4.CURJ. rewrite PB.uv_esub, PB.uv_eadd, F5, F6.
    rewrite (Z.mod_small (seg + wlen) (2 ^ 64)) by lia. rewrite Z.mod_small by lia. lia. }
  apply expr_eqb_eq in A16.
  assert (HWP1 : uv E1 (PB4.pv_wptr pv) = wend - uv E1 (EVar 49)) by (rewrite A16; exact HCJ).
  assert (HWP : uv E' (PB4.pv_wptr lv) = wend - uv E1 (EVar 49)) by (rewrite L14; exact HWP1).
  assert (H49 : APC.expr_vars_lt (CC.cp_nx c) (EVar 49) = true).
  { rewrite <- (PSB.nth_cut _ _ _ _ _ IL). destruct Hi as [-> | ->]; vm_compute; reflexivity. }
  pose proof (PSB.lo_ge_sound E' M' _ _ _ HKc A13) as Hlo.
  rewrite (PB.uv_agree (CC.cp_nx c) E1 E' (EVar 49) Hag H49) in Hlo.
  rewrite HWP in HEQ.
  destruct (HPAX bm bd ltac:(rewrite L11; exact HC8) ltac:(rewrite L12; exact HC9)) as (bufm & HPA & Hlen & Hbuf).
  rewrite (HEQ bm bd bufm), L8, L9, L10 in HPA.
  set (ps2 := PSS.upd psc (uv E1 (PB4.pv_st pv)) (uv E1 (PB4.pv_sst pv)) (uv E1 (PB4.pv_nst pv)) bm bd (uv E1 ce) (uv E1 pe) bufm
