  assert (HlenEq : length bufm = length buf) by (apply Nat2Z.inj; rewrite Hlen, L13; exact (eq_sym HC6)).
  assert (HW2 : PML.wf_ps ps2) by exact (PSX.wf_upd_same psc bd (uv E1 ce) (uv E1 pe) bufm _ HW Hbufeq).
  assert (Hwl1 : PML.winlen psc = wend - uv E1 (PB4.pv_wptr pv)) by (unfold psc, PSI.ps_of; rewrite HC4; apply PSB.winlen_of; lia).
  assert (Hwl2 : PML.winlen ps2 = uv E1 (EVar 49)) by (unfold ps2, PSS.upd; rewrite PSB.winlen_of by lia; lia).
  assert (HB2 : PML.buf_bound ps2 B).
  { destruct HB as [HB1 HB3]. split; [|exact HB3].
    change (PML.buf_need ps2) with (PML.buf_need psc). change (PML.ps_buf ps2) with bufm. change (PML.ps_buf psc) with buf in HB1.
    rewrite HlenEq, Hwl2. rewrite Hwl1, HWP1 in HB1. lia. }
  assert (FV : L5C.agree_on M1 M' (V + 8) 40) by exact (PSB.frame_vis_leaf I i c k ps1 _ E1 E' R' M1 M' model1 IL HA HagE' Hag HLF).
  assert (HCX : PSI.CX I ps2 M') by (apply (PSB.CX_same I M1 M' psc ps2 HWS FV); try reflexivity; exact HlenEq).
  assert (HLSg : PML.ls_ok g M') by exact (PSB.ls_frame M1 M' g FRI (PSI.iHG I) HS).
  destruct (nums_sound E' M' _ lv ce HKc A12) as (N1 & N2 & N3 & N4 & N5 & N6).
  assert (Hst : 0 <= PML.ps_st ps2 <= 255) by (change (PML.ps_st ps2) with (uv E1 (PB4.pv_st pv)); rewrite <- L8; exact N2).
  destruct (hcut_facts _ Hst) as (J1 & J2 & J3 & J4 & J5 & J6 & J7 & J8).
  pose proof (PSI.RANK_range ps2) as HRR.
  exists (hcut (PML.ps_st ps2)), ps2, (uv E1 (EVar 49)), (PSI.RANK ps2).
  split; [exact J1|].
  split; [symmetry; exact J4|].
  split; [exact HPA|].
  split; [reflexivity|].
  split.
