    split; [exact (wf_stk ps2 HW2)|]. exact J3. }
  split; [rewrite Hden; reflexivity|].
  split; [exact (ph_ec0 i E1 E' M' model1 _ HA' HKc HagE' A4)|].
  split.
  { intros _. rewrite (reg_at E' (CA.ps_reglist ps1) R' 11%nat 11%bv HRL) by (vm_compute; reflexivity).
    apply expr_eqb_eq in A14. rewrite A14. apply PB.edenot_of_uv. exact HWP. }
  split.
  { unfold PSR2.SEMF. split; [exact HLSg|]. split; [exact HW2|]. split; [exact HB2|]. split; [exact HCX|]. split; [lia|].
    split; [intros Q; exfalso; exact (J7 Q)|]. split; [exact (X2 Hi0)|]. intros _. lia. }
  rewrite J8. pose proof (meas_val c E1 R1 M1 cls HAt HagE Hcls) as HM.
  destruct cls as [z|z0]; cbv beta iota in HM, A19; apply Z.eqb_eq in A19.
  - rewrite HM, A19. lia.
  - subst z0. destruct HM as (HM & _ & HV50 & _). rewrite HM.
    assert (HRk : PSI.RANK ps2 <= uv E1 (EVar 50)).
    { destruct Hi as [Hi|Hi].
      - exfalso. rewrite <- (PSB.nth_cut _ _ _ _ _ IL), Hi in Hcls. vm_compute in Hcls. discriminate Hcls.
      - change (PSI.RANK ps2) with (PSI.RANK psc). exact (HR (or_intror (or_intror (or_intror Hi)))). }
    lia.
Qed.

