Lemma pa_is_lit : forall o z, PSM3.is_lit o z = true -> o = Some (ELit z).
Proof. intros o z H. destruct o as [e|]; cbn in H; [|discriminate H]. destruct e; cbn in H; try discriminate H. apply Z.eqb_eq in H. subst. reflexivity. Qed.
Lemma pa_is_z : forall o z, PSM3.is_z o z = true -> o = Some z.
Proof. intros o z H. destruct o as [v|]; cbn in H; [|discriminate H]. apply Z.eqb_eq in H. subst. reflexivity. Qed.
Lemma pa_is_none : forall (A : Type) (o : option A), PSM3.is_none o = true -> o = None.
Proof. intros A o H. destruct o; cbn in H; [discriminate H | reflexivity]. Qed.
Lemma pa_rank_pos : forall ps0, PML.ps_more ps0 = true -> 1 <= PSI.RANK ps0.
Proof. intros ps0 H. unfold PSI.RANK. rewrite H. destruct (_ =? _); [lia|]. destruct (_ || _)%bool; lia. Qed.
Lemma pa_bb_stop : forall ps0 st' sst' nst' bd bcap' bptr' buf' w B0, PML.buf_bound ps0 B0 -> PML.wf_ps ps0 -> length buf' = length (PML.ps_buf ps0) -> w = PML.ps_win ps0 ->
  PML.buf_bound (PSS.upd ps0 st' sst' nst' false bd bcap' bptr' buf' w) B0.
Proof.
  intros ps0 st' sst' nst' bd bcap' bptr' buf' w B0 (HB1 & HB2) HW0 Hl Hw. subst w. pose proof (PSB.buf_need_range ps0 HW0) as Hbn.
  split; [|exact HB2].
  assert (Q1 : PML.buf_need (PSS.upd ps0 st' sst' nst' false bd bcap' bptr' buf' (PML.ps_win ps0)) = 0) by reflexivity.
  assert (Q2 : PML.winlen (PSS.upd ps0 st' sst' nst' false bd bcap' bptr' buf' (PML.ps_win ps0)) = PML.winlen ps0) by reflexivity.
  assert (Q3 : PML.ps_buf (PSS.upd ps0 st' sst' nst' false bd bcap' bptr' buf' (PML.ps_win ps0)) = buf') by reflexivity.
  rewrite Q1, Q2, Q3, Hl. lia.
Qed.
Lemma leaf_reAcc : forall i c k ps1, is_leaf i c k ps1 (CC.TOther LPC) -> kind_of i = KInv -> CC.leaf_ok (hl_segs L) G.CPS AMB3 K PML.fp_ok i c ps1.
Proof.
  intros i c k ps1 IL Hk.
  pose proof (CH2.leaves_all_sound _ _ _ reAcc_ok _ _ _ _ _ IL) as X. unfold PSM4.reAcc_chk in X. cbv beta iota in X. rewrite Hk in X.
  lazymatch type of X with (if ?b then _ else _) = true => change b with true in X end. cbv beta iota zeta in X.
  destruct (PSM2.ldelta i c ps1) as [[[[[pv lv] pe] ce] d]|] eqn:HLD; [|cbv beta iota in X; discriminate X].
  destruct (PSM4.meas_cls c) as [[z|z0]|] eqn:HMC; cbv beta iota in X; [discriminate X| |discriminate X].
  unfold PSM4.reL_common in X.
  repeat match goal with H : (_ && _)%bool = true |- _ => apply andb_prop in H; destruct H end.
  match goal with H : Z.eqb (SR.ps_pc ps1) _ = true |- _ => apply Z.eqb_eq in H; rename H into Hpc end.
  match goal with H : PSM3.is_lit (PSM2.d_st d) _ = true |- _ => apply pa_is_lit in H; rename H into Dst end.
  match goal with H : PSM3.is_z (PSM2.d_more d) _ = true |- _ => apply pa_is_z in H; rename H into Dm end.
  match goal with H : PSM3.is_z (PSM2.d_done d) _ = true |- _ => apply pa_is_z in H; rename H into Dd end.
  match goal with H : PSM3.is_none (PSM2.d_sst d) = true |- _ => apply pa_is_none in H; rename H into Dsst end.
  match goal with H : PSM3.is_none (PSM2.d_nst d) = true |- _ => apply pa_is_none in H; rename H into Dnst end.
  match goal with H : negb (PSM2.d_clr d) = true |- _ => apply negb_true_iff in H; rename H into Dclr end.
  match goal with H : Z.eqb (PSM2.d_adv d) _ = true |- _ => apply Z.eqb_eq in H; rename H into Dadv end.
  match goal with H : PSM2.rng_is _ (PB4.pv_st pv) _ = true |- _ => rename H into Rst end.
  match goal with H : PSM2.rng_is _ (PB4.pv_more pv) _ = true |- _ => rename H into Rmore end.
  match goal with H : expr_eqb (PB4.pv_wptr pv) PSM4.CURJ = true |- _ => apply expr_eqb_eq in H; rename H into Hwp end.
  match goal with H : Z.eqb z0 _ = true |- _ => apply Z.eqb_eq in H; rename H into Hz0 end.
  match goal with H : PSM2.in_loop i = true |- _ => rename H into Hloop end.
  assert (Hi4 : (i = I_HLO \/ i = I_HHI \/ i = I_HN \/ i = I_L) /\ i <> 0%nat).
  { match goal with H : (_ || Nat.eqb i _)%bool = true |- _ =>
      repeat (apply orb_prop in H as [H|H]); apply Nat.eqb_eq in H; (split; [tauto | rewrite H; cbv [I_HLO I_HHI I_HN I_L]; lia]) end. }
  destruct Hi4 as (Hi4 & Hi0).
  pose proof L_facts as (LF1 & LF2 & LF3 & LF4 & LF5 & LF6 & LF7 & LF8).
  apply (reent_leaf I i c k ps1 LPC IL Hpc); [assumption|].
  intros E1 R1 E' R' M1 M' model1 HAt HA HA' HX Hag HLF HagE' HKc HRL.
  pose proof HA as (_ & _ & HagE1 & _).
  pose proof (meas_val c E1 R1 M1 (inr z0) HAt HagE1 HMC) as MV. cbv beta iota in MV. destruct MV as (MV1 & MV2 & MV3 & MV4 & MV5).
  unfold PSI.XI in HX. destruct HX as (X1 & X2 & X3 & HX).
  rewrite Hk, (PSB.lview_vw _ _ _ _ _ _ _ (ldelta_lview _ _ _ _ _ _ _ _ HLD)) in HX.
  destruct HX as (bm & bd & stack & buf & HC & HLS & HW & HB & HCX & HR & HE0).
  destruct (PSB.leaf_state I i c k ps1 _ pv lv pe ce d E1 R1 E' R' M1 M' model1 bm bd stack buf IL HLD HAt HA Hag HLF HC)
    as (_ & HK & _ & L1 & L2 & L3 & L4 & L5 & L6 & L7 & (AG1 & AG2 & AG3) & L8 & L9 & L10 & L11 & L12 & L13 & L14 & L15 & L16 & HSB & FR2 & FRI & HPAX & Hden & HEQ).
  pose proof HC as (HC1 & HC2 & HC3 & HC4 & HC5 & HC6 & HC6b & HC7 & HC8 & HC9).
  rewrite Dst in L8. rewrite Dsst in L9. rewrite Dnst in L10. rewrite Dm in L11. rewrite Dd in L12. rewrite Dclr in L13. cbn [PSB.newv] in L8, L9, L10, L11, L12, L13.
  rewrite Dadv, Z.add_0_r, Hwp, MV4 in L14.
  assert (Hbmt : bm = true) by (apply PSB.b2z_inj1; rewrite <- HC8, <- AG2; exact (PSB.rng_is_sound E' M' _ _ _ HKc Rmore)). subst bm.
  assert (Hst1 : uv E1 (PB4.pv_st pv) = PML.ST_ACCEPT) by (rewrite <- AG1; exact (PSB.rng_is_sound E' M' _ _ _ HKc Rst)).
  destruct (HPAX false true L11 L12) as (bufm & HPA & Hlen & _).
  rewrite (HEQ false true bufm) in HPA. rewrite L8, L9, L10, PB2.uv_lit in HPA by lia. rewrite L13 in Hlen.
  assert (HW2 : PML.wf_ps (PSS.upd (PSI.ps_of pv pe ce E1 true bd stack buf) PML.ST_DONE (uv E1 (PB4.pv_sst pv)) (uv E1 (PB4.pv_nst pv)) false true (uv E1 ce) (uv E1 pe) bufm
                             (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend)))
    by (apply PSS.wf_stop; [exact HW | exact (proj1 HW) | exact (proj1 (proj2 HW))]).
  exists I_L, (PSS.upd (PSI.ps_of pv pe ce E1 true bd stack buf) PML.ST_DONE (uv E1 (PB4.pv_sst pv)) (uv E1 (PB4.pv_nst pv)) false true (uv E1 ce) (uv E1 pe) bufm
                 (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend)), (uv E1 (EVar 49)), 0.
  split; [exact LF1|]. split; [symmetry; exact LF4|]. split; [exact HPA|].
  split; [cbn [PSS.upd PML.ps_win]; rewrite L14; reflexivity|].
  split.
  { unfold NUMS. rewrite LF5.
    pose proof (nums_sound E' M' (SR.ps_cells ps1) lv ce HKc ltac:(assumption)) as (NS1 & NS2 & NS3 & NS4 & NS5 & NS6).
    pose proof (wf_stk _ HW2) as (WS1 & WS2).
