Lemma leaf_rePop : forall i c k ps1 pc, is_leaf i c k ps1 (CC.TOther pc) -> pc = LPC \/ pc = L0PC -> kind_of i = KPop -> CC.leaf_ok (hl_segs L) G.CPS AMB3 K PML.fp_ok i c ps1.
