  unfold PSM4.reL_common in Kcom. apply andb_prop in Kcom as [Kcom Knums]. apply andb_prop in Kcom as [Kcom Kec]. apply andb_prop in Kcom as [Kpc Kall].
  apply Z.eqb_eq in Kpc. apply Nat.ltb_lt in Kg1.
  destruct (PSM2.d_st d) as [est|] eqn:Dst; [|discriminate Kdst]. destruct est; try discriminate Kdst.
  lazymatch type of Kdst with ((?v =? _)%nat = true) => apply Nat.eqb_eq in Kdst; subst v end.
  destruct (PSM2.d_more d) eqn:Dmore; [discriminate Kdm|]. destruct (PSM2.d_done d) eqn:Ddone; [discriminate Kdone|].
  destruct (PSM2.d_sst d) eqn:Dsst; [discriminate Ksst|]. destruct (PSM2.d_nst d) eqn:Dnst; [discriminate Knst|].
  destruct (PSM2.d_clr d) eqn:Dclr; [discriminate Kclr|].
  assert (Hi0 : i <> 0%nat) by (intros E0i; subst i; vm_compute in KP; discriminate KP).
