  rewrite (PSB.nth_cut _ _ _ _ _ IL) in Hx.
  assert (HX8 : uv E' (PB4.pv_st lv) = x).
  { rewrite LL8, <- Hx. unfold PB.uv. cbn [edenot]. rewrite <- (proj1 Hag _ Kg1). reflexivity. }
