  pose proof HW as (Ws & Wn & _).
  destruct (HPAX true bd ltac:(rewrite LL11; exact HC8) ltac:(rewrite LL12; exact HC9)) as (bufm & HPA & Hlen & _).
  destruct (PSS.wf_pop ps0 stack x (uv E1 (PB4.pv_sst pv)) (uv E1 (PB4.pv_nst pv)) bd (uv E1 ce) (uv E1 pe) bufm (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend) HW eq_refl Hcom eq_refl Ws Wn) as (Wf2 & Hxk).
  set (ps2 := PML.PS x (uv E1 (PB4.pv_sst pv)) (uv E1 (PB4.pv_nst pv)) true bd (PML.ps_level ps0) stack (PML.ps_sb ps0) (PML.ps_scap ps0) (uv E1 ce) (uv E1 pe) bufm (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend)) in Wf2.
