    assert (Hn1 : PML.buf_need ps0 = 0).
    { unfold PML.buf_need, ps0, PSI.ps_of. cbn [PML.ps_more PML.ps_st andb].
      destruct (Z.eqb_spec (uv E1 (PB4.pv_st pv)) PML.ST_STRING) as [Y|Y]; [|reflexivity].
      exfalso. unfold PML.comment_or_cr, PML.ST_CR in Hcom. unfold PML.ST_STRING in Y. lia. }
    assert (Hw2 : PML.winlen ps2 = wend - uv E' (PB4.pv_wptr lv)) by (unfold ps2; apply PSB.winlen_of; lia).
    assert (Hw0 : PML.winlen ps0 = wend - uv E1 (PB4.pv_wptr pv)) by (unfold ps0, PSI.ps_of; rewrite HC4; apply PSB.winlen_of; lia).
    rewrite Hn1, Hw0 in HB1. rewrite Hn0, Hw2. unfold ps2 at 1. cbn [PML.ps_buf]. unfold ps0, PSI.ps_of in HB1. cbn [PML.ps_buf] in HB1. lia. }
  assert (CX2 : PSI.CX I ps2 M').
  { destruct HCL as (HL1 & HL2). split; [split|].
    - exact (PSSC.lvl_pop ps0 stack x _ _ bd _ _ bufm _ HL1 eq_refl eq_refl).
    - intros _. exact (HL2 eq_refl).
    - intros Y. unfold ps2 in Y. discriminate Y. }
  assert (HLSg : PML.ls_ok g M') by exact (PSB.ls_frame M1 M' g FRI (PSI.iHG I) HS).
  assert (HST0 : st0 <> PML.ST_ACCEPT) by exact (X2 Hi0).
  pose proof (nums_sound E' M' (SR.ps_cells ps1) lv ce HKc Knums) as (N1 & N2 & N3 & N4 & N5 & N6).
  pose proof (wf_stk ps2 Wf2) as (SK1 & SK2).
  assert (NUMSc : forall j, jmin j = 0 -> (forall st, strange j st) -> NUMS I j ps2 (wend - uv E' (PB4.pv_wptr lv)) 1).
  { intros j Hj Hs. unfold NUMS. rewrite Hj.
