  assert (HEC : PML.u32 M' E 0) by exact (ec0_at i E1 E' M' model1 (SR.ps_cells ps1) HA' HKc HagE' Kec).
  assert (Hden2 : CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps2) by (rewrite Hden; reflexivity).
