    split; [exact Lt|]. split; [rewrite Lp; exact Kp|]. split; [exact HPA|]. split; [apply Hwin2; reflexivity|].
    split; [apply NUMSc; [exact Lj | exact Ls]|]. split; [exact Hden2|]. split; [exact HEC|]. split; [rewrite Lh; intros Y; discriminate Y|].
