        { unfold ps0, PSI.RANK, PSI.ps_of. cbn [PML.ps_more PML.ps_st]. destruct Y as [Y|Y]; apply Z.eqb_eq in Y; rewrite Y; vm_compute; intros Q; discriminate Q. }
        pose proof (HR Kin) as HR1. change (bv_unsigned (ev E1 50)) with (uv E1 (EVar 50)) in HR1. lia.
