Lemma pv_push : forall ps s' x bd' bc bp buf' w',
  PML.wf_ps ps -> PMCUR.lvl_ok ps -> PML.ps_more ps = true -> PML.ps_st ps = x ->
  (s' = 3 /\ In x [1; 7; 9; 10; 11; 12; 13] \/ s' = 28 /\ x = 5) ->
  PML.wf_ps (PML.PS s' (PML.ps_sst ps) (PML.ps_nst ps) true bd' (PML.ps_level ps) (PML.ps_stack ps ++ [x]) (PML.ps_sb ps) (PML.ps_scap ps) bc bp buf' w') /\
  PMCUR.lvl_ok (PML.PS s' (PML.ps_sst ps) (PML.ps_nst ps) true bd' (PML.ps_level ps) (PML.ps_stack ps ++ [x]) (PML.ps_sb ps) (PML.ps_scap ps) bc bp buf' w') /\
  PML.buf_need (PML.PS s' (PML.ps_sst ps) (PML.ps_nst ps) true bd' (PML.ps_level ps) (PML.ps_stack ps ++ [x]) (PML.ps_sb ps) (PML.ps_scap ps) bc bp buf' w') = 0.
Proof.
  intros ps s' x bd' bc bp buf' w' HW HL Hm Hx Hc.
  pose proof HW as (W1 & W2 & _ & W4 & _).
  assert (Hn : ~ In s' PMCUR.ICS).
  { intros Hi. apply PSSC.icsb_spec in Hi. destruct Hc as [(-> & _)|(-> & _)]; vm_compute in Hi; discriminate Hi. }
  split; [|split].
  - destruct Hc as [(-> & He)|(-> & Hx5)].
    + assert (He' : PML.is_expect (PML.ps_st ps)) by (unfold PML.is_expect; rewrite Hx; exact He).
      rewrite <- Hx.
      exact (proj1 (PSS.wf_push_slash ps (PML.ps_sst ps) (PML.ps_nst ps) bd' bc bp buf' w' (PML.ps_sb ps) (PML.ps_scap ps) HW Hm He' W4 W1 W2)).
    + rewrite Hx5 in Hx |- *.
      exact (proj1 (PSS.wf_push_cr ps (PML.ps_sst ps) (PML.ps_nst ps) bd' bc bp buf' w' (PML.ps_sb ps) (PML.ps_scap ps) HW Hm Hx W4 W1 W2)).
  - apply PSSC.lvl_push; [exact HL | exact Hm | intros Hi; rewrite Hx; exact Hi | exact Hn].
  - destruct Hc as [(-> & _)|(-> & _)]; reflexivity.
Qed.
Lemma leaf_reVec : forall i c k ps1, is_leaf i c k ps1 (CC.TOther LPC) -> kind_of i = KVec -> CC.leaf_ok (hl_segs L) G.CPS AMB3 K PML.fp_ok i c ps1.
Proof.
  intros i c k ps1 IL KV.
  pose proof (CH2.leaves_all_sound _ _ _ reVec_ok i c k ps1 _ IL) as CHK.
  unfold PSM4.reVec_chk in CHK. rewrite Z.eqb_refl, KV in CHK. cbn [andb] in CHK.
  destruct (PSM2.ldelta i c ps1) as [[[[[pv lv] pe] ce] d]|] eqn:HLD; [|discriminate CHK].
  cbv beta iota zeta in CHK.
  destruct (PSM4.meas_cls c) as [[z1|z0]|] eqn:MC; try discriminate CHK.
  destruct (CAX.cell_at (CC.cp_know c) (EVar 2) (-120) 1) as [[x| | | | | | |]|] eqn:CXe; try discriminate CHK.
  cbv beta iota zeta in CHK.
  apply andb_prop in CHK as [CHK D0c]. apply andb_prop in CHK as [CHK Hst]. apply andb_prop in CHK as [CHK Rst].
  apply andb_prop in CHK as [CHK Rmore]. apply andb_prop in CHK as [CHK Dclr]. apply andb_prop in CHK as [CHK Dnst].
  apply andb_prop in CHK as [CHK Dsst]. apply andb_prop in CHK as [CHK Ddone]. apply andb_prop in CHK as [CHK Dmore].
  apply andb_prop in CHK as [CHK Hz0]. apply andb_prop in CHK as [RLC Hloop].
  unfold PSM4.reL_common in RLC. apply andb_prop in RLC as [RLC Rnums]. apply andb_prop in RLC as [RLC Rhas]. apply andb_prop in RLC as [Rpc Rall].
  apply Z.eqb_eq in Rpc. apply Z.leb_le in Hz0.
  destruct (PSM4.d0_of pv) as [d0|] eqn:D0; [|discriminate D0c]. apply Z.leb_le in D0c.
  destruct (PSM2.d_more d) eqn:Dm; [discriminate Dmore|]. destruct (PSM2.d_done d) eqn:Dd; [discriminate Ddone|].
  destruct (PSM2.d_sst d) eqn:Ds; [discriminate Dsst|]. destruct (PSM2.d_nst d) eqn:Dn; [discriminate Dnst|].
  destruct (PSM2.d_clr d) eqn:Dc; [discriminate Dclr|].
  destruct (PSM2.d_st d) as [[s'| | | | | | |]|] eqn:Dst; cbn [PSM3.is_lit andb orb] in Hst; try discriminate Hst.
  assert (Hcase : s' = 3 /\ In x [1; 7; 9; 10; 11; 12; 13] \/ s' = 28 /\ x = 5).
  { apply orb_prop in Hst as [Hs|Hs]; apply andb_prop in Hs as [Hs1 Hs2]; apply Z.eqb_eq in Hs1.
    - left. split; [exact Hs1|]. apply existsb_exists in Hs2 as (y & Hy & Hxy). apply Z.eqb_eq in Hxy. subst y. exact Hy.
    - right. split; [exact Hs1|]. apply Z.eqb_eq in Hs2. exact Hs2. }
  assert (Hsr : 0 <= s' <= 28) by (destruct Hcase as [(-> & _)|(-> & _)]; lia).
  assert (Hi0 : i <> 0%nat) by (intros Hi; rewrite Hi in KV; vm_compute in KV; discriminate KV).
  destruct L_facts as (Lt & Lh & Ls & Lpc & Lj & Lin & Ln0 & Lm).
  apply (reent_leaf I i c k ps1 LPC IL Rpc Rall).
  intros E1 R1 E' R' M1 M' model1 HAt HA HA' HX Hag HLF HagE' HKc HRL.
  pose proof HA as (_ & _ & HagE & _).
  unfold PSI.XI in HX. destruct HX as (X1 & X2 & X3 & HX). rewrite KV in HX.
  rewrite (PSB.lview_vw _ _ _ _ _ _ _ (ldelta_lview _ _ _ _ _ _ _ _ HLD)) in HX.
  destruct HX as (bm & bd & stack & buf & HC & HLS1 & HXV).
  rewrite (PSB.nth_cut _ _ _ _ _ IL), CXe in HXV.
  destruct HXV as (old & Hstk & HW & HB & HCL). subst stack.
  destruct (PSB.leaf_state I i c k ps1 _ pv lv pe ce d E1 R1 E' R' M1 M' model1 bm bd (old ++ [x]) buf IL HLD HAt HA Hag HLF HC)
    as (_ & _ & _ & Q1 & Q2 & Q3 & Q4 & Q5 & Q6 & Q7 & (AG1 & AG2 & AG3) & Q8 & Q9 & Q10 & Q11 & Q12 & Q13 & Q14 & Q15 & Q16 & _ & _ & FRI & HPAX & Hden & _).
  pose proof HC as (HC1 & HC2 & HC3 & HC4 & HC5 & HC6 & HC6b & HC7 & HC8 & HC9).
  rewrite Dst in Q8. rewrite Ds in Q9. rewrite Dn in Q10. rewrite Dm in Q11. rewrite Dd in Q12. rewrite Dc in Q13.
  cbn [PSB.newv] in Q9, Q10, Q11, Q12. cbv beta iota in Q8, Q13.
  rewrite (PB2.uv_lit E' s') in Q8 by lia.
  pose proof (PSB.rng_is_sound E' M' _ _ _ HKc Rmore) as Hm1. rewrite AG2, HC8 in Hm1. apply PSB.b2z_inj1 in Hm1. subst bm.
  pose proof (PSB.rng_is_sound E' M' _ _ _ HKc Rst) as Hx1. rewrite AG1 in Hx1. subst x.
  destruct (HPAX true bd ltac:(rewrite Q11; exact HC8) ltac:(rewrite Q12; exact HC9)) as (bufm & HPA & Hlen & _).
  destruct (meas_val c E1 R1 M1 _ HAt HagE MC) as (Hmeas & Hj49 & Hr50 & Hcurj & Hz0r).
  destruct (curj_val E1 (uv E1 (EVar 49)) Hcurj Hj49 pv d0 D0) as (Hwp & Hd0).
  destruct (nums_sound E' M' _ lv ce HKc Rnums) as (N1 & N2 & N3 & N4 & N5 & N6).
  pose proof (PSI.WIN I) as (W0 & W1 & _).
  set (ps1o := PSI.ps_of pv pe ce E1 true bd old buf) in *.
  assert (Eps1o : ps1o = PSI.ps_of pv pe ce E1 true bd old buf) by reflexivity. clearbody ps1o.
  assert (Eo_st : PML.ps_st ps1o = uv E1 (PB4.pv_st pv)) by (rewrite Eps1o; reflexivity).
  assert (Eo_sst : PML.ps_sst ps1o = uv E1 (PB4.pv_sst pv)) by (rewrite Eps1o; reflexivity).
  assert (Eo_nst : PML.ps_nst ps1o = uv E1 (PB4.pv_nst pv)) by (rewrite Eps1o; reflexivity).
  assert (Eo_more : PML.ps_more ps1o = true) by (rewrite Eps1o; reflexivity).
  assert (Eo_lvl : PML.ps_level ps1o = uv E1 (PB4.pv_level pv)) by (rewrite Eps1o; reflexivity).
  assert (Eo_stk : PML.ps_stack ps1o = old) by (rewrite Eps1o; reflexivity).
  assert (Eo_sb : PML.ps_sb ps1o = uv E1 (PB4.pv_sb pv)) by (rewrite Eps1o; reflexivity).
  assert (Eo_scap : PML.ps_scap ps1o = uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv)) by (rewrite Eps1o; reflexivity).
  assert (Eo_buf : PML.ps_buf ps1o = buf) by (rewrite Eps1o; reflexivity).
  assert (Eo_wl : PML.winlen ps1o = wend - uv E1 (PB4.pv_wptr pv)) by (rewrite Eps1o; unfold PSI.ps_of; rewrite HC4; apply PSB.winlen_of; lia).
  assert (Hps2 : PSI.ps_of lv pe ce E' true bd (old ++ [uv E1 (PB4.pv_st pv)]) bufm =
    PML.PS s' (PML.ps_sst ps1o) (PML.ps_nst ps1o) true bd (PML.ps_level ps1o) (PML.ps_stack ps1o ++ [uv E1 (PB4.pv_st pv)]) (PML.ps_sb ps1o) (PML.ps_scap ps1o)
      (uv E1 ce) (uv E1 pe) bufm (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend)).
  { rewrite Eo_sst, Eo_nst, Eo_lvl, Eo_stk, Eo_sb, Eo_scap. unfold PSI.ps_of. rewrite Q8, Q9, Q10, Q1, Q2, Q4, Q5, Q6, Q7. reflexivity. }
  rewrite Hps2 in HPA.
  destruct HCL as (HLV & HCL2). destruct HB as (HB1 & HB2). rewrite Eo_buf, Eo_wl in HB1.
  pose proof (PSB.buf_need_range ps1o HW) as Hbn1. pose proof HW as (HW1 & HW2 & _).
  destruct (pv_push ps1o s' (uv E1 (PB4.pv_st pv)) bd (uv E1 ce) (uv E1 pe) bufm (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend) HW HLV Eo_more Eo_st Hcase)
    as (Hwf2 & Hlv2 & Hbn2).
  exists I_L. eexists. exists (wend - uv E' (PB4.pv_wptr lv)), 3.
  split; [exact Lt|]. split; [symmetry; exact Lpc|]. split; [exact HPA|].
  split; [cbn [PML.ps_win]; f_equal; lia|].
  split.
  { unfold NUMS. cbn [PML.ps_level PML.ps_st PML.ps_sst PML.ps_nst PML.ps_buf PML.ps_bcap PML.ps_stack PML.ps_scap].
    pose proof (wf_stk _ Hwf2) as Hstk2. cbn [PML.ps_stack PML.ps_scap] in Hstk2.
    unfold PSI.wlen. rewrite Lj.
    split; [lia|]. split; [lia|]. split; [lia|]. split; [lia|]. split; [lia|]. split; [exact Hstk2|]. exact (Ls s'). }
  split; [rewrite Hden; unfold PML.ps_blocks; cbn [PML.ps_bptr PML.ps_bcap PML.ps_sb PML.ps_scap]; rewrite Eo_sb, Eo_scap; reflexivity|].
  split; [exact (ec0_at i E1 E' M' model1 _ HA' HKc HagE' Rhas)|].
  split; [intros Q; rewrite Lh in Q; discriminate Q|].
  split.
  { unfold SEMF. split; [exact (PSB.ls_frame M1 M' g FRI (PSI.iHG I) HLS1)|]. split; [exact Hwf2|].
    split; [unfold PML.buf_bound; split; [|exact HB2]; rewrite Hbn2, PSB.winlen_of by lia; cbn [PML.ps_buf]; lia|].
    split; [unfold PSI.CX, PSI.CL, PSI.STOPOK; split; [split; [exact Hlv2 | intros _; cbn [PML.ps_level]; exact (HCL2 Eo_more)] | intros Q; cbn [PML.ps_more] in Q; discriminate Q]|].
    split; [exact (proj2 (PSI.RANK_range _))|]. split; [intros Q; exfalso; exact (Ln0 Q)|]. split; [exact (X2 Hi0)|].
    intros _. exact (X3 Hloop). }
  rewrite Lm, Hmeas. lia.
Qed.

Definition PTS (i : nat) (c : CC.cutpoint) (E1 : env) (M' : mem) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 4 "S14;A1;o29;Y6;00;Y3;0;N5;A3;i2;i1;r2;o35;A1;k152;#3;A2;k321;vSCFG_P;vI;A1;k499;A1;k344;r4;A2;k64;vSCFG_P;vI;A3;k500;i1;i1;#6;A1;k329;r5;N49;A2;k84;#0;A2;k326;r7;#10;A3;i2;i1;#9;#11;A1;o58;o81;Li;Ri10;Lc;Ri42;LE1;Ri26;LM';RP~RA1;i30;#0;A1;i3;A1;i30;A1;o29;#1;A2;i143;i204;Lps2;Ri204;A2;i143;i1;Lcode;Ri1;A2;i143;i495;Lg';Ri495;A2;i47;A3;i2;i1;A2;k84;#0;A2;k326;r5;A2;k336;A2;k336;A1;k305;r6;k337;#2;r2;A2;i47;A3;k343;r4;A2;k126;vSCFG_P;vI;r3;A2;i47;A1;k205;r3;A2;i47;A3;k496;r4;A2;k146;vSCFG_P;vI;r3;A2;i47;A2;k323;r3;A2;k138;vSCFG_P;vI;A2;i47;A3;k330;r4;A2;k130;vSCFG_P;vI;r2;A2;i47;P~R#4;A3;i2;i23;A1;k216;r4;o37;A2;i47;A2;k320;r1;r4;A2;i47;A2;i123;A3;i2;i495;r1;#5;A2;i47;A3;i2;i495;r1;A1;k328;#5;#4;A2;i47;A3;i2;A1;i27;A2;i144;i1;i1;A2;k347;r5;A4;k40;k348;r7;k296;A1;o77;A2;i144;i0;i0;A1;k349;r3;A2;i47;P~RA3;i2;i23;A1;k497;r7;o86;A3;i2;i1;r3;o35;P~R#3;A2;i47;A4;k324;vSCFG_P;vI;r4;r5;A2;i47;A3;i2;i1;A3;k498;i1;i1;#6;#7;A2;i47;A2;i47;A2;k60;A2;k133;vSCFG_P;vI;#8;A2;k60;#8;#7;A2;i47;P~RA3;i2;i23;A1;k501;r8;o86;A3;k117;i1;A1;k220;r5;A3;o76;i1;k317;A3;o76;i1;k222;A1;o77;i1;P~RA3;i2;i23;A1;k250;r8;o86;m23;RNL~Ri23;pA2;k237;A1;k502;r9;k503;2;#12;A2;i123;A2;k60;A2;k56;#9;#13;#11;A2;i47;#12;A2;k60;A2;k56;A1;k325;r5;#13;A2;k84;#0;A2;k326;r7;N50;").
Lemma pt_state : forall i c k ps1 pc E1 R1 E' R' (M1 M' : mem) model1, is_leaf i c k ps1 (CC.TOther pc) -> kind_of i = KPt ->
  (if PSM2.cur_cut i then PB.has (SR.ps_cells ps1) (KWord (SA Pb 200) 8 (EVar (PSM3.a0v_of c))) else Nat.eqb (length (CC.cp_F c)) 1) = true -> (70 <= CC.cp_nx c)%nat ->
  match CC.cp_F c with [_; (_, o1, _)] => Z.eqb o1 200 | _ => true end = true ->
  CC.At (hl_segs L) c E1 R1 M1 -> HAMB i E1 M1 model1 -> XI i E1 M1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> env_agree GT.NF E0 E' -> know_ok RSEGS E' M' (SR.ps_cells ps1) ->
  PTS i c E1 M'.
Proof.
  intros i c k ps1 pc E1 R1 E' R' M1 M' model1 IL K1 Xcur Hnx70 Xo200 HAt HA HX Hag HLF HagE' HKc.
  unfold PSI.XI in HX. destruct HX as (X1 & X2 & X3 & HX). rewrite K1 in HX.
  pose proof (PSI.OBJR I) as (O1 & O2 & O3 & O4 & O5 & O6 & O7). pose proof (PSI.SPF I) as (_ & S2 & _ & S4 & _).
  pose proof (PSB.nth_cut _ _ _ _ _ IL) as Hcut. unfold PSI.pt_post in HX. rewrite Hcut in HX. cbv zeta in HX.
  destruct HX as (ps2 & code & g' & cw & T1 & T2 & T3 & T4 & T5 & T6 & T7 & T8 & T9 & T10 & Tsk & T11 & T12).
  assert (AGV : forall v, (v < CC.cp_nx c)%nat -> bv_unsigned (ev E' v) = bv_unsigned (ev E1 v)) by (intros v Hv; destruct Hag as [Hev _]; rewrite (Hev v Hv); reflexivity).
  destruct (PSB.bls2' _ _ _ _ _ IL) as (pe2 & ce2 & sbe & sce & HBL). destruct (PSB.leaf_nf _ _ _ _ _ IL) as (_ & _ & Hfoot).
  destruct (PSB.own_blocks I i E1 M1 model1 pe2 ce2 sbe sce HA HBL) as ((C0 & C1 & C2 & C3 & C4) & (D0 & D1 & D2 & D3 & D4) & _).
  pose proof T10 as T10b.
  rewrite HBL, !PB.den_cons in T10b. change (CH2.den E1 []) with (@nil (Z * Z)) in T10b. unfold PML.ps_blocks in T10b. injection T10b as Eb1 Eb2 Eb3 Eb4.
  pose proof (PSB.CEIL I) as CL. destruct (PSB.FRZ I E' HagE') as (F1 & _ & _ & F4 & _).
  assert (GR : mem_grows M1 M') by exact (CC.lf_grows _ _ _ _ _ _ _ HLF).
  assert (HWK : PML.win_ok M' LBo ps2) by exact (PB2.win_ok_fr M1 M' GR LBo ps2 T3).
  assert (ST : estart E' (SA (EVar 2) (-10096)) = sp - 10096) by (unfold estart; cbn [a_base a_off]; fold (uv E' (EVar 2)); rewrite F4; lia).
  assert (PT : forall o, estart E' (SA Pb o) = P + o) by (intros o; unfold estart; cbn [a_base a_off]; fold (uv E' Pb); rewrite F1; reflexivity).
  pose proof (PSI.iAP2 I) as AP2. unfold PML.apart in AP2.
  pose proof (PSB.frame_vis_leaf I i c k ps1 _ E1 E' R' M1 M' model1 IL HA HagE' Hag HLF) as HVIS.
  assert (FIN : PML.parser_at M' P ps2 -> PML.ec_at M' E code -> PML.ls_ok g' M' -> PTS i c E1 M').
  { intros Q1 Q2 Q3. unfold PTS. exists ps2, code, g'.
    split; [exact T9|]. split; [exact Q1|]. split; [exact T2|]. split; [exact HWK|]. split; [exact T4|]. split; [exact Q2|].
    split; [exact T6|]. split; [exact Q3|]. split; [exact T8|]. split; [exact T10|]. split; [exact Tsk|].
    intros Q0. destruct (T12 Q0) as (Y1 & Y2). split; [exact (PSB.CX_mem I M1 M' ps2 Y1 HVIS) | exact Y2]. }
  assert (Hg' : g' <> PML.LS0) by (destruct T8 as [->|[-> _]]; [exact (PSI.iHG I) | apply PSSC.regJ_nz]).
  unfold PSM2.cur_cut in T11, Xcur. rewrite Hcut in T11, Xcur. unfold PSM2.foot_all in Hfoot. apply andb_prop in Hfoot as [Hfoot _]. unfold PSM2.foot_chk in Hfoot.
  destruct (CC.cp_F c) as [|r0 [|[[b1 o1] n1] [|]]] eqn:HF; try discriminate.
  +
    apply PSB.reg_eqb_eq in Hfoot. subst r0. subst cw.
    set (F := [(sp - 10096, 10096)] : list L5.range).
    assert (FR : L5.frame_but F M1 M').
    { intros x Hx. apply (CC.lf_frame _ _ _ _ _ _ _ HLF). unfold SGP.outside. rewrite HF. constructor; [|constructor]. unfold PSM2.STKREG. cbv beta iota. rewrite ST. unfold elenZ. cbn [edenot]. rewrite u64_of_Z by lia.
      pose proof (Hx (sp - 10096, 10096) ltac:(left; reflexivity)) as Q. unfold L5.in_rng in Q. cbn [fst snd] in Q. lia. }
    assert (OUTLO : forall a n, 0 <= a -> a + n <= sp - 10096 -> PB2.out F a n).
    { intros a n A0 A1. split; [lia|]. split; [lia|]. intros q Hq rg [<-|[]]; unfold L5.in_rng; cbn [fst snd]; lia. }
    assert (OUTHI : forall a n, sp <= a -> a + n <= 2 ^ 47 -> PB2.out F a n).
    { intros a n A0 A1. split; [lia|]. split; [lia|]. intros q Hq rg [<-|[]]; unfold L5.in_rng; cbn [fst snd]; lia. }
    apply FIN.
    * replace (PML.ps_set_win ps2 (PML.ps_win ps2)) with ps2 in T1 by (destruct ps2; reflexivity).
      apply (PB2.parser_at_fr F M1 M' FR GR P ps2); [apply OUTHI; lia | apply OUTLO; unfold hl_ceil in *; lia | apply OUTLO; unfold hl_ceil in *; lia | exact T1].
    * apply (PB2.ec_at_fr F M1 M' FR GR E code); [apply OUTHI; lia | exact T5].
    * apply (PB2.ls_ok_fr F M1 M' FR g' Hg'); [apply OUTLO; lia | exact T7].
  +
    apply andb_prop in Hfoot as [Hfoot H3]. apply andb_prop in Hfoot as [H1 H2]. apply PSB.reg_eqb_eq in H1. apply expr_eqb_eq in H2. subst r0 b1.
    apply orb_prop in H3 as [H3|H3]; apply andb_prop in H3 as [H3 H4]; apply Z.eqb_eq in H3; apply expr_eqb_eq in H4; subst o1 n1;
      [|discriminate Xo200].
    destruct T11 as (p0 & e0 & -> & Hw2 & Hp0).
    set (F := [(sp - 10096, 10096); (P + 200, 8)] : list L5.range).
    assert (FR : L5.frame_but F M1 M').
    { intros x Hx. apply (CC.lf_frame _ _ _ _ _ _ _ HLF). unfold SGP.outside. rewrite HF. constructor; [|constructor; [|constructor]]; unfold PSM2.STKREG; cbv beta iota.
      - rewrite ST. unfold elenZ. cbn [edenot]. rewrite u64_of_Z by lia. pose proof (Hx (sp - 10096, 10096) ltac:(left; reflexivity)) as Q. unfold L5.in_rng in Q. cbn [fst snd] in Q. lia.
      - rewrite PT. unfold elenZ. cbn [edenot]. rewrite u64_of_Z by lia. pose proof (Hx (P + 200, 8) ltac:(right; left; reflexivity)) as Q. unfold L5.in_rng in Q. cbn [fst snd] in Q. lia. }
    assert (OUTLO : forall a n, 0 <= a -> a + n <= sp - 10096 -> PB2.out F a n).
    { intros a n A0 A1. split; [lia|]. split; [lia|]. intros q Hq rg [<-|[<-|[]]]; unfold L5.in_rng; cbn [fst snd]; lia. }
    assert (OUTHI : forall a n, sp <= a -> a + n <= 2 ^ 47 -> (a + n <= P + 200 \/ P + 208 <= a) -> PB2.out F a n).
    { intros a n A0 A1 A2. split; [lia|]. split; [lia|]. intros q Hq rg [<-|[<-|[]]]; unfold L5.in_rng; cbn [fst snd]; lia. }
    apply FIN.
    * replace ps2 with (PML.ps_set_win ps2 (Some (bv_unsigned (ev E1 (CC.cp_nx c - APC.NCS + 4)), e0))) by (destruct ps2; cbn [PML.ps_win] in Hw2; cbn [PML.ps_set_win]; rewrite Hw2; reflexivity).
      apply (PSX.pa_fr_cur F M1 M' FR GR P ps2 p0 e0); [apply OUTHI; lia | apply OUTHI; lia | apply OUTLO; unfold hl_ceil in *; lia | apply OUTLO; unfold hl_ceil in *; lia | exact T1 | | lia].
      pose proof (PB2.kword64_elim E' M' _ _ (P + 200) (PB.has_ok E' M' _ _ HKc Xcur) (PT 200)) as Q. unfold PB.uv in Q. cbn [edenot] in Q. unfold PSM3.a0v_of in Q.
      rewrite AGV in Q by (unfold APC.NCS; lia). exact Q.
    * apply (PB2.ec_at_fr F M1 M' FR GR E code); [apply OUTHI; lia | exact T5].
