Lemma leaf_rePt : forall i c k ps1 pc, is_leaf i c k ps1 (CC.TOther pc) -> pc = LPC \/ pc = L2PC \/ pc = L0PC -> kind_of i = KPt -> CC.leaf_ok (hl_segs L) G.CPS AMB3 K PML.fp_ok i c ps1.
Proof.
  intros i c k ps1 pc IL Hpc3 K1.
  pose proof (CH2.leaves_all_sound _ _ _ rePt_ok _ _ _ _ _ IL) as X. unfold PSM4.rePt_chk in X. cbv beta iota zeta in X.
  assert (HB : ((pc =? LPC) || (pc =? L2PC) || (pc =? L0PC))%bool = true) by (destruct Hpc3 as [ -> | [ -> | -> ] ]; reflexivity).
  rewrite HB, K1 in X. lazymatch type of X with (if ?b then _ else _) = true => change b with true in X end. cbv beta iota in X.
  apply andb_prop in X as [X Xm]. apply andb_prop in X as [X Xre]. apply andb_prop in X as [X Xo200]. apply andb_prop in X as [X Hnx].
  apply andb_prop in X as [X Xcur]. apply andb_prop in X as [X Xne]. apply andb_prop in X as [Xpc Xall].
  apply Z.eqb_eq in Xpc. apply Nat.leb_le in Hnx. apply Z.eqb_eq in Xre.
  assert (Hi0 : i <> 0%nat) by (intros ->; vm_compute in K1; discriminate K1).
  apply (PSR2.reent_leaf I i c k ps1 pc IL Xpc Xall).
  intros E1 R1 E' R' M1 M' model1 HAt HA HA' HX Hag HLF HagE' HKc HRL.
  destruct (pt_state i c k ps1 pc E1 R1 E' R' M1 M' model1 IL K1 Xcur Hnx Xo200 HAt HA HX Hag HLF HagE' HKc)
    as (ps2 & code & g' & Hcode & HPA & HWF & HWK & HBB & HEC & Hmore & HLS & Hg' & Hden & Hsk & H0).
  assert (AGV : forall v, (v < CC.cp_nx c)%nat -> bv_unsigned (ev E' v) = bv_unsigned (ev E1 v)) by (intros v Hv; destruct Hag as [Hev _]; rewrite (Hev v Hv); reflexivity).
  assert (Hc0 : code = 0).
  { apply orb_prop in Xne as [Xne|Xne]; [|exact (Hsk Xne)].
    pose proof (PSB.rng_is_sound E' M' _ _ 0 HKc Xne) as Q. unfold PB.uv in Q. cbn [edenot] in Q. unfold PSM3.nxg_of in Q.
    rewrite AGV in Q by (unfold APC.NCS; lia). rewrite <- Hcode. exact Q. }
  rewrite Hc0 in HEC, Hg', H0. destruct (H0 eq_refl) as (HCX & Hwe & Hws & Hu0 & Hil).
  assert (HLSg : PML.ls_ok g M') by (destruct Hg' as [<-|[_ Q]]; [exact HLS | exfalso; exact (Q eq_refl)]).
  assert (HEC0 : PML.u32 M' E 0) by (destruct HEC as (Q & _); exact Q).
  pose proof HX as (X1 & X2 & X3 & _).
  pose proof HA as (_ & _ & HagE1 & _).
  pose proof (PSI.WIN I) as (W0 & W1 & _).
  assert (Hwin : PML.ps_win ps2 = PB4.win_of (wend - PML.winlen ps2) wend /\ 0 <= PML.winlen ps2 <= wlen).
  { unfold PML.winlen, PB4.win_of, PSI.wlen.
    destruct (PML.ps_win ps2) as [[p e]|] eqn:Hw; cbn [PSA.wincells fst snd] in Hwe, Hws.
    - subst e. destruct (Z.eqb_spec wend 0) as [Hz|Hz].
      + exfalso. unfold PML.win_ok in HWK. rewrite Hw in HWK. destruct HWK as (ch & Hch & Hc1 & Hc2 & _).
        pose proof HA' as (_ & _ & _ & (cr & HH & _) & _).
        pose proof (PSI.iHIok I) as HOK. destruct HOK as [_ _ _ _ _ HWFh _].
        destruct (HWFh _ _ _ _ HH) as (Hbw & _). unfold CH2.cur in Hbw.
        first [destruct (Hbw _ (in_or_app _ _ _ (or_intror Hch))) as ((C0 & _) & _) | destruct (Hbw _ (in_or_app _ _ _ (or_introl Hch))) as ((C0 & _) & _)].
        cbn [fst] in C0. lia.
      + replace (wend - (wend - p)) with p by lia. split; [reflexivity | lia].
    - destruct (Z.eqb_spec wend 0) as [Hz|Hz]; [split; [reflexivity | lia] | lia]. }
  destruct Hwin as (Hwin & Hjv).
  destruct (nums_cx ps2 M' HWF HCX HBB ltac:(lia)) as (N1 & N2 & N3).
  destruct (wf_stk ps2 HWF) as (N4 & N5).
  pose proof (PSI.RANK_range ps2) as RR.
  pose proof HA' as (_ & _ & _ & (cr & _ & HCr) & _).
  pose proof HWF as (_ & _ & _ & Hscap & _).
  apply (PSI.cred_of_blocks I i E1 cr ps2 Hden Hscap) in HCr. destruct HCr as (_ & _ & Hbcap & _).
  destruct (PSM4.meas_cls c) as [[z|z0]|] eqn:Hmc; [| | discriminate Xm].
  -
    pose proof (meas_val c E1 R1 M1 _ HAt HagE1 Hmc) as Mv. cbv beta iota in Mv.
    apply andb_prop in Xm as [Xm Xst]. apply andb_prop in Xm as [Xm Xz]. apply andb_prop in Xm as [Xm Xp]. apply andb_prop in Xm as [Xu Xnl].
    apply Z.eqb_eq in Xp. rewrite Xp in *. apply Z.ltb_lt in Xz.
    destruct L0_facts as (Lt & Lh & Ls & Lpc & Ljm & Lil & Lmv).
    pose proof (PSB.rng_is_sound E' M' _ _ 17 HKc Xst) as Q17. destruct (PSB.FRZ I E' HagE') as (_ & _ & _ & _ & _ & _ & _ & F42 & _).
    rewrite F42 in Q17.
    exists I_L0, ps2, (PML.winlen ps2), (PSI.RANK ps2).
    split; [exact Lt|]. split; [symmetry; exact Lpc|]. split; [exact HPA|]. split; [exact Hwin|].
    split; [unfold PSR2.NUMS; rewrite Ljm; split; [lia|]; split; [exact RR|]; split; [exact N1|]; split; [exact N2|]; split; [split; [exact N3 | exact Hbcap]|]; split; [split; [exact N4 | exact N5] | apply Ls]|].
    split; [exact Hden|]. split; [exact HEC0|]. split; [intros Q; rewrite Lh in Q; discriminate Q|].
    split.
    + unfold PSR2.SEMF. split; [exact HLSg|]. split; [exact HWF|]. split; [exact HBB|]. split; [exact HCX|]. split; [lia|].
      split; [intros _ _ _; split; [left; unfold PML.ST_NUMBER; lia | destruct (Hu0 Xu) as [Q1|[Q1|[]]]; unfold PML.ST_ACCEPT, PML.ST_EXPECT_COMMA_OR_END, PML.ST_NUMBER, PML.ST_CR in *; intros [Q2|[Q2|[]]]; lia]|].
      split; [exact (X2 Hi0) | rewrite Lil; discriminate].
    + rewrite Lmv, Mv. lia.
  -
    pose proof (meas_val c E1 R1 M1 _ HAt HagE1 Hmc) as Mv. cbv beta iota in Mv. destruct Mv as (Mv & J49 & J50 & _ & Z5).
    apply andb_prop in Xm as [Xm Xl2]. apply andb_prop in Xm as [Xm Xp]. apply andb_prop in Xm as [Xil Xz5].
    specialize (Hil Xil). rewrite Xre in Hil.
    assert (U49 : uv E1 (EVar 49) = bv_unsigned (ev E1 49)) by reflexivity.
    assert (U50 : uv E1 (EVar 50) = bv_unsigned (ev E1 50)) by reflexivity.
    pose proof (X3 Xil) as Wl1.
    apply orb_prop in Xp as [Xp|Xp]; apply Z.eqb_eq in Xp; rewrite Xp in *.
    +
      assert (HL : (LPC =? L2PC) = false) by reflexivity. rewrite HL in Hil.
      destruct L_facts as (Lt & Lh & Ls & Lpc & Ljm & Lil & Lne & Lmv).
      exists I_L, ps2, (PML.winlen ps2), (PSI.RANK ps2).
      split; [exact Lt|]. split; [symmetry; exact Lpc|]. split; [exact HPA|]. split; [exact Hwin|].
      split; [unfold PSR2.NUMS; rewrite Ljm; split; [lia|]; split; [exact RR|]; split; [exact N1|]; split; [exact N2|]; split; [split; [exact N3 | exact Hbcap]|]; split; [split; [exact N4 | exact N5] | apply Ls]|].
      split; [exact Hden|]. split; [exact HEC0|]. split; [intros Q; rewrite Lh in Q; discriminate Q|].
      split.
      * unfold PSR2.SEMF. split; [exact HLSg|]. split; [exact HWF|]. split; [exact HBB|]. split; [exact HCX|]. split; [lia|].
        split; [intros Q; exfalso; exact (Lne Q)|]. split; [exact (X2 Hi0) | intros _; exact Wl1].
      * rewrite Lmv, Mv. lia.
    +
      rewrite Z.eqb_refl in Hil, Xl2. cbv beta iota in Xl2.
      pose proof (proj2 HAt) as HKn. rewrite LS in HKn. pose proof (PB.has_ok E1 M1 _ _ HKn Xl2) as K49.
      assert (K49' : 1 <= uv E1 (EVar 49)) by (destruct K49 as [K _]; exact K).
      destruct L2_facts as (Lt & Lh & Ls & Lpc & Ljm & Lil & Lne & Lmv).
      exists I_L2, ps2, (PML.winlen ps2), (PSI.RANK ps2).
      split; [exact Lt|]. split; [symmetry; exact Lpc|]. split; [exact HPA|]. split; [exact Hwin|].
      split; [unfold PSR2.NUMS; rewrite Ljm; split; [lia|]; split; [exact RR|]; split; [exact N1|]; split; [exact N2|]; split; [split; [exact N3 | exact Hbcap]|]; split; [split; [exact N4 | exact N5] | apply Ls]|].
      split; [exact Hden|]. split; [exact HEC0|]. split; [intros Q; rewrite Lh in Q; discriminate Q|].
      split.
      * unfold PSR2.SEMF. split; [exact HLSg|]. split; [exact HWF|]. split; [exact HBB|]. split; [exact HCX|]. split; [lia|].
        split; [intros Q; exfalso; exact (Lne Q)|]. split; [exact (X2 Hi0) | intros _; exact Wl1].
      * rewrite Lmv, Mv. lia.
Qed.
End E.
End PSE.
